namespace ghidra.app.plugin.core.compositeeditor;






using docking;
using docking.action;
using generic.theme;
using ghidra.util.exception;

public class ClearAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Clear Components";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static Icon ICON = new GIcon("icon.plugin.composite.editor.clear");
	private static string[] POPUP_PATH = new string[] { "Clear" };
	private static KeyStroke KEY_STROKE = KeyStroke.getKeyStroke(KeyEvent.VK_C, 0);

	public ClearAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {

		setDescription("Clear the selected components");
		setKeyBindingData(new KeyBindingData(KEY_STROKE));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		try {
			model.clearSelectedComponents();
		}
		catch (UsrException ue) {
			model.setStatus(ue.getMessage());
		}
		requestTableFocus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isClearAllowed();
	}

}
